    "body_html": "<p><strong>XL-BUNDLE</strong></p><p>Everything on this page is <strong>X-Large</strong>.</p><p>Choose exactly what you want from the three dropdowns. Select <strong>None</strong> for anything you don't want, so you can order one item, two items or the full set.</p><p><strong>Hoodie / Sweatshirt:</strong> None, Classic Hoodie, Printed Zip-Up Hoodie, Sweatshirt Design 1 or Sweatshirt Design 2.<br><strong>T-Shirt:</strong> None, Polo Shirt, Classic T-Shirt or Women's Fitted T-Shirt.<br><strong>Joggers:</strong> None, Logo Joggers, Leg Joggers, Printed Cuffed Joggers or Embroidered Cuffed Joggers.</p>",
